<?php
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/helpers.php';
Auth::requireAdmin();
$db = Database::getInstance();

if ($_SERVER['REQUEST_METHOD'] === 'POST' && Auth::verifyCSRFToken(postParam('csrf_token'))) {
    $action = postParam('action');
    $enrollmentId = postParam('enrollment_id', null, FILTER_VALIDATE_INT);
    if ($action === 'approve_enrollment' && $enrollmentId) approveEnrollment($enrollmentId, Auth::getCurrentUserId());
    if ($action === 'approve_completion' && $enrollmentId) approveAdminCompletion($enrollmentId);
    if ($action === 'assign_trainer' && $enrollmentId) assignTrainer($enrollmentId, postParam('trainer_id', null, FILTER_VALIDATE_INT));
}
$stats = [
    'users' => $db->getValue('SELECT COUNT(*) FROM users'),
    'students' => $db->getValue("SELECT COUNT(*) FROM users WHERE role = 'student'"),
    'trainers' => $db->getValue("SELECT COUNT(*) FROM users WHERE role = 'trainer'"),
    'courses' => $db->getValue("SELECT COUNT(*) FROM courses WHERE status = 'published'"),
    'enrollments' => $db->getValue('SELECT COUNT(*) FROM enrollments'),
    'pending' => $db->getValue("SELECT COUNT(*) FROM enrollments WHERE status = 'pending'"),
    'completed' => $db->getValue("SELECT COUNT(*) FROM enrollments WHERE status = 'completed'"),
    'messages' => $db->getValue("SELECT COUNT(*) FROM contact_messages WHERE status = 'new'"),
    'revenue' => (float) $db->getValue("SELECT COALESCE(SUM(amount), 0) FROM payments WHERE status = 'paid'")
];
$enrollments = $db->getAll("SELECT e.id, e.status, e.progress, e.student_completed_at, e.trainer_approved_at, c.title, u.name AS student_name, e.trainer_id FROM enrollments e JOIN courses c ON c.id=e.course_id JOIN users u ON u.id=e.user_id ORDER BY e.updated_at DESC");
$trainers = $db->getAll("SELECT id, name FROM users WHERE role = 'trainer' AND status = 'active' ORDER BY name");
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin Dashboard | ICTECH</title><link rel="stylesheet" href="../assets/css/style.css?v=20260902"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><main class="container py-5"><header class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><p class="text-secondary mb-1">ICTECH ADMIN CONSOLE</p><h1 class="mb-1">Operations Dashboard</h1><p class="text-muted mb-0">Manage learning delivery, content, and platform performance.</p></div><div class="d-flex gap-2 flex-wrap"><a href="courses.php" class="btn btn-primary">Manage Courses</a><a href="categories.php" class="btn btn-outline-primary">Categories</a><a href="payments.php" class="btn btn-outline-primary">Payments</a><a href="reports.php" class="btn btn-outline-primary">Reports</a><a href="settings.php#admin-access" class="btn btn-outline-primary">Admin Access</a><a href="create-trainer.php" class="btn btn-outline-primary">Create Trainer</a><a href="../logout.php" class="btn btn-outline-secondary">Logout</a></div></header><section class="row g-3 mb-5"><?php foreach ([['users','Total Users','fa-users','primary'],['students','Students','fa-user-graduate','info'],['trainers','Trainers','fa-chalkboard-user','warning'],['courses','Published Courses','fa-book-open','success'],['pending','Pending Enrollments','fa-hourglass-half','danger'],['completed','Completed Courses','fa-certificate','secondary'],['messages','New Messages','fa-envelope','dark']] as $stat): ?><div class="col-6 col-md-4 col-xl"><div class="card admin-stat-card h-100"><div class="card-body"><i class="fas <?php echo $stat[2]; ?> text-<?php echo $stat[3]; ?> mb-2"></i><div class="h3 mb-1"><?php echo (int) $stats[$stat[0]]; ?></div><small class="text-muted"><?php echo $stat[1]; ?></small></div></div></div><?php endforeach; ?><div class="col-12"><div class="card h-100"><div class="card-body"><div class="text-muted small mb-1">Total paid revenue</div><div class="h3 mb-0"><?php echo formatCurrency((float) $stats['revenue']); ?></div></div></div></div></div></section><section class="mb-4"><div class="card"><div class="card-body"><div class="d-flex flex-wrap gap-2"><?php foreach (['users.php','enrollments.php','payments.php','reports.php','testimonials.php','partners.php','contact-messages.php','settings.php'] as $page): ?><a href="<?php echo $page; ?>" class="btn btn-sm btn-outline-primary"><?php echo str_replace('-', ' ', pathinfo($page, PATHINFO_FILENAME)); ?></a><?php endforeach; ?></div></div></div></section><section class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h4 mb-1">Enrollment Workflow</h2><p class="text-muted mb-0">Approve requests, assign trainers, and authorize verified completion.</p></div><span class="badge text-bg-primary"><?php echo (int) $stats['enrollments']; ?> total</span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Student</th><th>Course</th><th>Status</th><th>Trainer</th><th>Actions</th></tr></thead><tbody><?php foreach ($enrollments as $item): ?><tr><td><?php echo h($item['student_name']); ?></td><td><?php echo h($item['title']); ?></td><td><span class="badge text-bg-<?php echo $item['status'] === 'completed' ? 'success' : ($item['status'] === 'active' ? 'primary' : 'warning'); ?>"><?php echo h($item['status']); ?></span> <?php echo (int) $item['progress']; ?>%</td><td><?php echo $item['trainer_id'] ? 'Assigned' : 'Unassigned'; ?></td><td><form method="post" class="d-flex gap-2 flex-wrap"><input type="hidden" name="csrf_token" value="<?php echo h(Auth::generateCSRFToken()); ?>"><input type="hidden" name="enrollment_id" value="<?php echo (int) $item['id']; ?>"><select name="trainer_id" class="form-select form-select-sm"><option value="">Assign trainer</option><?php foreach ($trainers as $trainer): ?><option value="<?php echo (int) $trainer['id']; ?>"><?php echo h($trainer['name']); ?></option><?php endforeach; ?></select><button name="action" value="assign_trainer" class="btn btn-sm btn-outline-primary">Assign</button><?php if ($item['status'] === 'pending'): ?><button name="action" value="approve_enrollment" class="btn btn-sm btn-primary">Approve</button><?php endif; ?><?php if ($item['trainer_approved_at']): ?><button name="action" value="approve_completion" class="btn btn-sm btn-success">Approve Completion</button><?php endif; ?></form></td></tr><?php endforeach; ?><?php if (!$enrollments): ?><tr><td colspan="5" class="text-center text-muted py-4">No enrollment activity yet.</td></tr><?php endif; ?></tbody></table></div></div></section></main></body></html>
